CREATE DATABASE IF NOT EXISTS ecommerce_db;
USE ecommerce_db;
CREATE TABLE ecommerce_data (
    `OrderID` VARCHAR(10) PRIMARY KEY NOT NULL,
    `OrderDate` DATE NULL,
    `CustomerID` VARCHAR(10) NULL,
    `CustomerSegment` VARCHAR(30) NULL,
    `Gender` VARCHAR(10) NULL,
    `Age` INT NULL,
    `City` VARCHAR(50) NULL,
    `State` VARCHAR(50) NULL,
    `ProductID` VARCHAR(10) NULL,
    `ProductName` VARCHAR(100) NULL,
    `Category` VARCHAR(50) NULL,
    `Subcategory` VARCHAR(50) NULL,
    `Quantity` INT NULL,
    `UnitPrice` DECIMAL(12,2) NULL,
    `DiscountPct` DECIMAL(5,2) NULL,
    `GrossSales` DECIMAL(12,2) NULL,
    `DiscountAmount` DECIMAL(12,2) NULL,
    `NetSales` DECIMAL(12,2) NULL,
    `Cost` DECIMAL(12,2) NULL,
    `Profit` DECIMAL(12,2) NULL,
    `PaymentMethod` VARCHAR(30) NULL,
    `OrderStatus` VARCHAR(20) NULL,
    `ExpectedDeliveryDate` DATE NULL,
    `DeliveryDate` DATE NULL,
    `DeliveryDays` DECIMAL(6,2) NULL,
    `ReturnedFlag` TINYINT NULL,
    `CancelledFlag` TINYINT NULL,
    `ReturnReason` VARCHAR(50) NULL,
    `RefundAmount` DECIMAL(12,2) NULL,
    `MarketingChannel` VARCHAR(30) NULL,
    `Campaign` VARCHAR(50) NULL,
    `Rating` DECIMAL(2,1) NULL,
    `DeliveryDelayDays` DECIMAL(6,2) NULL,
    `OnTimeDeliveryFlag` TINYINT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SELECT * FROM ecommerce_data;
-- Verify imported records
SELECT COUNT(*) AS total_records FROM ecommerce_data;

